record.field:
submission_model = env['x_hr.applicant_required_document_submission'].sudo()
action = False

for rec in records.sudo():
    line = rec.x_line_id
    checklist = rec.x_checklist_id or (line.x_checklist_id if line else False)
    applicant = rec.x_applicant_id or (checklist.x_applicant_id if checklist else False)
    document_type = (line.x_document_type_id if line else False) or rec.x_document_type_id

    if not applicant:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Applicant missing',
                'message': 'Cannot accept this submission because it is not linked to an applicant.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if not checklist:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Checklist missing',
                'message': 'Cannot accept this submission because it is not linked to a required document checklist.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if not line:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Checklist line missing',
                'message': 'Cannot accept this submission because it is not linked to a required document checklist line.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    requires_attachment = True
    if line and line.x_requires_attachment is not None:
        requires_attachment = bool(line.x_requires_attachment)
    elif document_type and document_type.x_requires_attachment is not None:
        requires_attachment = bool(document_type.x_requires_attachment)

    if requires_attachment and not rec.x_attachment_id:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Submitted attachment missing',
                'message': 'Cannot accept this submission because this checklist line requires an attachment.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    if line and line.x_document_code == 'bank_information':
        missing_bank_fields = []
        if not rec.x_bank_name:
            missing_bank_fields.append('Bank Name')
        if not rec.x_bank_branch:
            missing_bank_fields.append('Bank Branch')
        if not rec.x_account_number:
            missing_bank_fields.append('Account Number')

        if missing_bank_fields:
            action = {
                'type': 'ir.actions.client',
                'tag': 'display_notification',
                'params': {
                    'title': 'Bank information incomplete',
                    'message': 'Please complete required bank information before accepting: %s.' % ', '.join(missing_bank_fields),
                    'type': 'warning',
                    'sticky': False,
                }
            }
            continue

    reviewed_on = datetime.datetime.now()

    # Supersede earlier accepted evidence for the same checklist line.
    prior_accepted = submission_model.search([
        ('x_line_id', '=', line.id),
        ('x_state', '=', 'accepted'),
        ('id', '!=', rec.id),
    ])
    if prior_accepted:
        prior_accepted.write({
            'x_state': 'superseded',
        })

    submission_values = {
        'x_state': 'accepted',
        'x_reviewed_by_user_id': env.user.id,
        'x_reviewed_on': reviewed_on,
        'x_applicant_id': applicant.id,
        'x_checklist_id': checklist.id,
        'x_line_id': line.id,
    }

    if document_type:
        submission_values['x_document_type_id'] = document_type.id

    if not rec.x_source:
        submission_values['x_source'] = 'manual'

    if not rec.x_submitted_by_user_id:
        submission_values['x_submitted_by_user_id'] = env.user.id

    if not rec.x_submitted_on:
        submission_values['x_submitted_on'] = rec.create_date or reviewed_on

    rec.write(submission_values)

    line_values = {
        'x_status': 'accepted',
        'x_latest_accepted_submission_id': rec.id,
        'x_latest_accepted_attachment_id': rec.x_attachment_id.id if rec.x_attachment_id else False,
        'x_document_number': rec.x_document_number or False,
        'x_issuing_authority': rec.x_issuing_authority or False,
        'x_place_of_issue': rec.x_place_of_issue or False,
        'x_issue_date': rec.x_issue_date or False,
        'x_expiry_date': rec.x_expiry_date or False,
        'x_qualification_type': rec.x_qualification_type or False,
        'x_qualification_subject': rec.x_qualification_subject or False,
        'x_date_of_birth': rec.x_date_of_birth or False,
        'x_place_of_birth': rec.x_place_of_birth or False,
        'x_country_of_birth_id': rec.x_country_of_birth_id.id if rec.x_country_of_birth_id else False,
        'x_family_paper_number': rec.x_family_paper_number or False,
        'x_family_reference_number': rec.x_family_reference_number or False,
        'x_next_of_kin_name': rec.x_next_of_kin_name or False,
        'x_next_of_kin_phone': rec.x_next_of_kin_phone or False,
        'x_blood_type': rec.x_blood_type or False,
        'x_bank_name': rec.x_bank_name or False,
        'x_bank_branch': rec.x_bank_branch or False,
        'x_account_number': rec.x_account_number or False,
        'x_iban': rec.x_iban or False,
        'x_reviewed_by_user_id': env.user.id,
        'x_reviewed_on': reviewed_on,
    }

    line.write(line_values)

    if checklist.x_state in ('draft', 'in_review', 'ready_for_pdf'):
        checklist.write({
            'x_state': 'in_review',
            'x_reviewer_user_id': env.user.id,
        })

    rec.message_post(
        body='Required document submission accepted. The linked F-0003 checklist line was updated.'
    )
    checklist.message_post(
        body='Accepted evidence for required document line: %s.' % (
            line.x_document_name_en or line.x_document_name_ar or line.display_name
        )
    )
    applicant.message_post(
        body='Required document submission accepted for F-0003 checklist: %s.' % (
            line.x_document_name_en or line.x_document_name_ar or line.display_name
        )
    )

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}

submission_model = env['x_hr.applicant_required_document_submission'].sudo()
action = False

for rec in records.sudo():
    line = rec.x_line_id
    checklist = rec.x_checklist_id or (line.x_checklist_id if line else False)
    applicant = rec.x_applicant_id or (checklist.x_applicant_id if checklist else False)

    if not applicant:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Applicant missing',
                'message': 'Cannot reject this submission because it is not linked to an applicant.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if not checklist:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Checklist missing',
                'message': 'Cannot reject this submission because it is not linked to a required document checklist.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if not line:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Checklist line missing',
                'message': 'Cannot reject this submission because it is not linked to a required document checklist line.',
                'type': 'warning',
                'sticky': True,
            }
        }
        continue

    if not rec.x_reviewer_note:
        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'Reviewer note required',
                'message': 'Please enter a reviewer note / rejection reason before rejecting this submission.',
                'type': 'warning',
                'sticky': False,
            }
        }
        continue

    reviewed_on = datetime.datetime.now()

    rec.write({
        'x_state': 'rejected',
        'x_reviewed_by_user_id': env.user.id,
        'x_reviewed_on': reviewed_on,
        'x_submitted_on': rec.x_submitted_on or rec.create_date or reviewed_on,
    })

    accepted = submission_model.search([
        ('x_line_id', '=', line.id),
        ('x_state', '=', 'accepted'),
        ('x_attachment_id', '!=', False),
    ], order='x_reviewed_on desc, id desc', limit=1)

    if accepted:
        line.write({
            'x_status': 'accepted',
            'x_latest_accepted_submission_id': accepted.id,
            'x_latest_accepted_attachment_id': accepted.x_attachment_id.id,
            'x_reviewed_by_user_id': env.user.id,
            'x_reviewed_on': reviewed_on,
        })
    else:
        note = line.x_notes or ''
        rejection_note = rec.x_reviewer_note or ''
        if rejection_note and rejection_note not in note:
            note = (note + '\n\nRejected submission note: ' + rejection_note).strip()

        line.write({
            'x_status': 'resubmission_requested',
            'x_latest_accepted_submission_id': False,
            'x_latest_accepted_attachment_id': False,
            'x_reviewed_by_user_id': env.user.id,
            'x_reviewed_on': reviewed_on,
            'x_notes': note,
        })

    if checklist.x_state in ('draft', 'in_review', 'ready_for_pdf'):
        checklist.write({
            'x_state': 'in_review',
            'x_reviewer_user_id': env.user.id,
        })

    rec.message_post(
        body='Required document submission rejected. Rejection reason: %s' % rec.x_reviewer_note
    )
    checklist.message_post(
        body='Rejected evidence for required document line: %s.' % (
            line.x_document_name_en or line.x_document_name_ar or line.display_name
        )
    )
    applicant.message_post(
        body='Required document submission rejected for F-0003 checklist: %s.' % (
            line.x_document_name_en or line.x_document_name_ar or line.display_name
        )
    )

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
